"""Triton implementation of ``aten::adaptive_max_pool1d``.

The generic implementation reshapes ``(N, C, L)`` to ``(N, C, 1, L)`` and
delegates to ``adaptive_max_pool2d``.  That kernel tiles the output in two
dimensions and walks the window with a 2-D grid, so on the benchmark shapes
(the second adaptive dimension is always 1) it spent most of its time on
redundant coordinate arithmetic.  This version pools the flat
``(N * C, L)`` view directly: one lane per output position, one sequential
max over the adaptive window, which measured 6-82x faster than the delegated
form and 3.8-52x faster than the native operator.

Each lane reproduces the ATen tie-break rules: the first equal maximum wins
and the last NaN wins (a NaN always replaces the accumulator).
"""

import logging
from typing import Tuple

import torch
import triton
import triton.language as tl

from flag_gems.utils import libentry
from flag_gems.utils.limits import get_dtype_min

logger = logging.getLogger(__name__)

# Dtypes the native operator accepts; ATen rejects the integral and bool
# dtypes, so the wrapper mirrors that instead of silently computing them.
_SUPPORTED_DTYPES = (torch.float16, torch.bfloat16, torch.float32, torch.float64)

# Output positions per program. 512 was flat-to-best over the benchmark shapes
# (up to 512 outputs per row) and keeps the per-lane window walk short.
_BLOCK = 512
_NUM_WARPS = 4
# grid.x hardware limit; larger launches are rejected by the backend.
_MAX_GRID = 65535


@libentry()
@triton.jit(do_not_specialize=["in_len", "out_len", "n_rows"])
def _adaptive_max_pool1d_kernel(
    input_ptr,
    output_ptr,
    indices_ptr,
    in_len,
    out_len,
    n_rows,
    BLOCK: tl.constexpr,
    GRID_STRIDE: tl.constexpr,
    WIDE: tl.constexpr,
):
    pid = tl.program_id(0)
    num_tiles = tl.cdiv(out_len, BLOCK)

    # One program walks a strided set of output tiles; rows are decoded from
    # the flat tile index so any (N * C) batch size fits a capped grid.
    total_tiles = n_rows * num_tiles
    for tile in tl.range(pid, total_tiles, GRID_STRIDE):
        row = tile // num_tiles
        tile_in_row = tile % num_tiles
        pos = tile_in_row * BLOCK + tl.arange(0, BLOCK)
        valid = pos < out_len

        # Adaptive window: start = floor(i * L / Lout),
        #                 end   = ceil((i + 1) * L / Lout).
        # The products are int32 (the default index dtype) unless
        # in_len * out_len + out_len - 1 exceeds int32, which large tables can
        # reach (e.g. in_len = out_len = 65536); WIDE selects the int64 form
        # only there.  Always using int64 would cost ~5x here: 64-bit division
        # per lane dominates at the sizes the operator is normally used at.
        if WIDE:
            pos64 = pos.to(tl.int64)
            start = (pos64 * in_len) // out_len
            end = ((pos64 + 1) * in_len + out_len - 1) // out_len
        else:
            start = (pos * in_len) // out_len
            end = ((pos + 1) * in_len + out_len - 1) // out_len
        base = row.to(tl.int64) * in_len

        min_val = get_dtype_min(input_ptr.dtype.element_ty)
        best = tl.full((BLOCK,), min_val, dtype=input_ptr.dtype.element_ty)
        best_idx = tl.full((BLOCK,), -1, dtype=tl.int64)

        # The widest adaptive window is at most ceil(L / Lout) + 1.
        max_window = tl.cdiv(in_len, out_len) + 1
        for k in range(max_window):
            cur = start + k
            in_window = valid & (cur < end)
            value = tl.load(input_ptr + base + cur, mask=in_window, other=min_val)
            # ATen keeps the first equal maximum but the last encountered NaN.
            is_new_max = (
                (value > best) | (value != value) | (best_idx < 0)
            ) & in_window
            best = tl.where(is_new_max, value, best)
            best_idx = tl.where(is_new_max, cur.to(tl.int64), best_idx)

        out_off = row.to(tl.int64) * out_len + pos
        tl.store(output_ptr + out_off, best, mask=valid)
        tl.store(indices_ptr + out_off, best_idx, mask=valid)


def _parse_output_size(output_size):
    if isinstance(output_size, int):
        return output_size
    if isinstance(output_size, (list, tuple)):
        if len(output_size) == 1:
            return output_size[0]
        raise RuntimeError(
            "adaptive_max_pool1d() argument 'output_size' should contain one "
            f"int (got {len(output_size)})"
        )
    raise TypeError(
        f"output_size must be int or list/tuple, got {type(output_size).__name__}"
    )


def adaptive_max_pool1d(
    input: torch.Tensor, output_size
) -> Tuple[torch.Tensor, torch.Tensor]:
    """
    Adaptive max pooling operation over 1D input.

    Args:
        input: Input tensor of shape (N, C, L)
        output_size: Target output size (int or list of length 1)

    Returns:
        Tuple of (output, indices) where:
        - output: Pooled tensor of shape (N, C, output_size)
        - indices: Indices of max values, shape (N, C, output_size)
    """
    logger.debug("GEMS ADAPTIVE_MAX_POOL1D")

    # Input validation.  ATen also accepts the unbatched (C, L) form; it is
    # handled by pooling a (1, C, L) view and dropping the batch dim.
    assert input.ndim in (
        2,
        3,
    ), f"adaptive_max_pool1d expects 2D or 3D input, got {input.ndim}D"
    unbatched = input.ndim == 2
    orig_shape = list(input.shape)
    if unbatched:
        input = input.unsqueeze(0)
    if input.dtype not in _SUPPORTED_DTYPES:
        raise NotImplementedError(
            f"adaptive_max_pool1d not implemented for '{input.dtype}'"
        )
    input = input.contiguous()

    out_len = _parse_output_size(output_size)
    if out_len < 0:
        raise RuntimeError(
            "adaptive_max_pool1d: output_size must not be negative, got " f"{out_len}"
        )
    in_n, in_c, in_len = input.shape
    if in_len == 0:
        raise RuntimeError(
            "adaptive_max_pool1d(): Expected input to have non-zero size for "
            f"non-batch dimensions, but input has sizes {orig_shape} "
            "with dimension 2 being empty."
        )
    output = torch.empty((in_n, in_c, out_len), device=input.device, dtype=input.dtype)
    indices = torch.empty((in_n, in_c, out_len), device=input.device, dtype=torch.int64)
    if output.numel() == 0:
        if unbatched:
            output = output.squeeze(0)
            indices = indices.squeeze(0)
        return output, indices

    num_tiles = triton.cdiv(out_len, _BLOCK)
    total_tiles = in_n * in_c * num_tiles
    # Cap grid.x at the 65535 hardware limit and let each program walk a
    # strided set of tiles.
    grid_size = min(total_tiles, _MAX_GRID)
    grid = (grid_size,)
    # Largest intermediate is out_len * in_len + out_len - 1 in the window
    # bounds; only large tables need the int64 form of that arithmetic.
    wide = out_len * in_len + out_len - 1 > 0x7FFFFFFF

    _adaptive_max_pool1d_kernel[grid](
        input,
        output,
        indices,
        in_len,
        out_len,
        in_n * in_c,
        BLOCK=_BLOCK,
        GRID_STRIDE=grid_size,
        WIDE=wide,
        num_warps=_NUM_WARPS,
    )
    if unbatched:
        output = output.squeeze(0)
        indices = indices.squeeze(0)
    return output, indices
